function process(input) {
  // Extract data from webhook payload
  const payload = input.payload || {};

  // Match external system format
  const searchId = payload.searchId || `search-${Date.now()}`;
  const query = payload.query || '';
  const moduleTypes = payload.moduleTypes || ['COMPANY_OVERVIEW', 'DECISION_MAKER', 'EMAIL_DISCOVERY'];
  const filterCriteria = payload.configuration?.filterCriteria || {};
  const callbackUrl = payload.callbackUrl;

  // Map to our internal format
  return {
    searchId,
    searchQuery: query,
    targetTitles: 'CEO, CTO, VP of Engineering, VP of Marketing, VP of Sales',
    maxResults: 10,
    includeLinkedIn: true,
    includeEmail: true,
    includePhone: false,
    callbackUrl: callbackUrl,
    moduleTypes,
    filterCriteria,
    incrementalUpdates: payload.configuration?.incrementalUpdates !== false,
    validationThresholds: payload.configuration?.validationThresholds || {
      companyScore: 60,
      contactScore: 70,
      emailScore: 65
    }
  };
}

function process(input) {
  // Extract and process the target titles
  const titles = input.targetTitles.split(',').map(title => title.trim()).filter(title => title.length > 0);

  // If incremental updates are enabled, send initial progress update
  if (input.incrementalUpdates && input.callbackUrl) {
    // Send a progress update to callback URL
    try {
      fetch(input.callbackUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          searchId: input.searchId,
          status: 'in_progress',
          stage: 'COMPANY_OVERVIEW',
          progress: 10,
          timestamp: new Date().toISOString(),
          results: {
            metadata: {
              moduleType: 'COMPANY_OVERVIEW',
              completedSearches: [],
              validationScores: {}
            }
          }
        })
      }).catch(err => console.error('Error sending progress update:', err));
    } catch (error) {
      console.error('Failed to send progress update:', error);
    }
  }

  return {
    ...input,
    processedTitles: titles
  };
}

