function process(input) {
  // Format response according to external system requirements
  const searchId = input.searchId || `search-${Date.now()}`;

  // Extract company and contact data
  const companies = [];
  const contacts = [];

  if (Array.isArray(input)) {
    input.forEach(item => {
      if (item.company) {
        companies.push({
          name: item.company.name,
          website: item.company.website,
          industry: item.company.industry,
          size: item.company.size,
          location: item.company.location,
          description: item.company.description,
          validationScore: item.company.validationScore || 85
        });
      }

      if (item.contact) {
        contacts.push({
          name: item.contact.name,
          role: item.contact.role || item.contact.title,
          department: item.contact.department,
          email: item.contact.email,
          nameConfidenceScore: item.contact.nameConfidenceScore || 90,
          emailValidationScore: item.contact.emailValidationScore || 80,
          seniority: item.contact.seniority || 80,
          isDecisionMaker: true
        });
      }
    });
  }

  // Format response according to external system requirements
  const response = {
    searchId: searchId,
    status: 'completed',
    timestamp: new Date().toISOString(),
    results: {
      companies: companies,
      contacts: contacts,
      metadata: {
        moduleType: 'EMAIL_DISCOVERY',
        completedSearches: ['COMPANY_OVERVIEW', 'DECISION_MAKER', 'EMAIL_DISCOVERY'],
        validationScores: {
          companyValidation: 85,
          contactValidation: 90
        }
      }
    }
  };

  return response;
}
